-- Create "signing_keys" table
CREATE TABLE "signing_keys" ("id" character varying(40) NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "alg" character varying NOT NULL, "public_key" bytea NOT NULL, "status" character varying NOT NULL, "private_key_ciphertext" character varying(200) NULL, "activated_at" timestamptz NULL, "retired_at" timestamptz NULL, "tenant_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "signing_keys_tenants_signing_keys" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "signing_keys_activated_at" CHECK ((((status)::text <> 'pending'::text) OR (activated_at IS NULL)) AND (((status)::text <> 'active'::text) OR (activated_at IS NOT NULL))), CONSTRAINT "signing_keys_alg_valid" CHECK ((alg)::text = ANY (ARRAY['ed25519'::text])), CONSTRAINT "signing_keys_ciphertext" CHECK ((private_key_ciphertext IS NULL) OR ((private_key_ciphertext)::text ~ '^v1\.[a-z0-9-]{1,32}\.[A-Za-z0-9_-]{80}$'::text)), CONSTRAINT "signing_keys_ed25519_len" CHECK (((alg)::text <> 'ed25519'::text) OR (length(public_key) = 32)), CONSTRAINT "signing_keys_id_format" CHECK ((id)::text ~ '^sk_[a-z2-7]{26}$'::text), CONSTRAINT "signing_keys_retired_at" CHECK (((status)::text = 'retired'::text) = (retired_at IS NOT NULL)), CONSTRAINT "signing_keys_retired_destroyed" CHECK (((status)::text = 'retired'::text) = (private_key_ciphertext IS NULL)), CONSTRAINT "signing_keys_status_valid" CHECK ((status)::text = ANY (ARRAY['pending'::text, 'active'::text, 'retired'::text])));
-- Create index "signingkey_tenant_id" to table: "signing_keys"
CREATE INDEX "signingkey_tenant_id" ON "signing_keys" ("tenant_id");
-- Create index "signingkey_tenant_id_id" to table: "signing_keys"
CREATE UNIQUE INDEX "signingkey_tenant_id_id" ON "signing_keys" ("tenant_id", "id");
-- Create index "signingkey_tenant_id_status" to table: "signing_keys"
CREATE UNIQUE INDEX "signingkey_tenant_id_status" ON "signing_keys" ("tenant_id", "status") WHERE ((status)::text = ANY (ARRAY['active'::text, 'pending'::text]));
